def aggregate_results(selected, results):
    if len(set(selected)) != len(selected):
        raise ValueError('Selected paths must be unique')
    by_path = {}
    invalid = False
    for item in results:
        path = item.get('path')
        if path not in selected or path in by_path:
            invalid = True
            continue
        by_path[path] = item
    completed = 0
    findings = []
    for path in selected:
        item = by_path.get(path, {})
        comments = item.get('comments')
        if item.get('status') != 'completed' or not isinstance(comments, list):
            invalid = True
            continue
        if any(not isinstance(comment, dict) for comment in comments):
            invalid = True
            continue
        completed += 1
        findings.extend(comments)
    complete = not invalid and completed == len(selected) and bool(selected)
    state = 'clean' if complete and not findings else 'findings' if complete else 'incomplete'
    return {'state': state, 'completed': completed, 'findings': findings}

